/**
 * 负责奇迹商人从实际库存选择赠予。输入为当前原体与验证后的技能／收货选择，输出为赠予、反噬及交易事实。
 * 阵营只在原点晚查实际值，同值组件替换不增加引用撤权；新请求、关窗或首付款之前拒绝已退休源。
 * 原 ownerCurrent 仍复验已付反噬的生命与身份，目标／知识不按运行墓碑裁剪。Good 授予正常返回后，
 * 商人库存、成交记录和事实仍按原完成前缀继续；Wolf 在商人库存首写付款，异常不退款或回滚。
 */
import { closeMerchantTrade, recordMerchantTrade } from "./state";

import type { MiracleSkill } from "@ai-werewolf-arena/game-contract";

import { COMPONENT } from "../../../../core/domain/components/names";
import { isRoleExecutionRetired } from "../../../../core/domain/role-execution-authority";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, Phase, WitchSelfHealRule } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { grantNightAbility } from "../night-ability-grants";
import { canMerchantTrade, getMerchantState } from "./state";

const committed = new WeakMap<World, Set<number>>();
export function hasMerchantNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
function recordCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}

export const MIRACLE_MERCHANT_STAGE: NightStageHandler = {
  id: "miracle_merchant",
  priority: 125,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const actorId of ctx.getAliveByRole(Role.MiracleMerchant)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getMerchantState(role),
        life = captureNightLife(ctx.world, actorId);
      if (!state || !life || ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good) continue;
      const privateState = role.privateState;
      const ownerCurrent = () =>
        ctx.isCurrent() &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.MiracleMerchant &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Good &&
        role.privateState === privateState &&
        getMerchantState(role) === state &&
        livingNightLife(ctx.world, life);
      // 先完成原体／库存的原有序复验，再否决新交易；纯 ownerCurrent 仍供已付反噬使用。
      const current = () => ownerCurrent() && canMerchantTrade(state, day) && !isRoleExecutionRetired(role);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        // 候选捕获的原 getter 已全部执行；退休源不再打开新的请求，目标名单本身不按墓碑过滤。
        if (isRoleExecutionRetired(role)) break;
        const action = targets.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(actorId, ["bestow_ability"], {
                stage: "miracle_merchant",
                requiresAction: false,
                ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
              }),
            )
          : null;
        if (!current()) break;
        if (action === null) {
          // 空回复也会写当日关窗；只在首写之前拒绝，既有 callee 和局部实参顺序不改。
          if (isRoleExecutionRetired(role)) break;
          closeMerchantTrade(state, day);
          recordCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "merchant_trade_skipped",
            payload: { actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== "bestow_ability") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || valid.sanitizedCall?.name !== "bestow_ability") continue;
        const { target_id: targetId, skill } = valid.sanitizedCall.args,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          ctx.world.getComponent(targetId, COMPONENT.Camp)?.camp !== target.camp ||
          target.role.privateState !== target.privateState
        )
          continue;
        const failure = target.camp === Camp.Wolf;
        // 原 args／目标末字段与阵营判断已完成；Wolf 在 record 内首付，Good 由原赠予 owner 首装。
        if (isRoleExecutionRetired(role)) break;
        if (!failure) {
          const base = {
            id: "gift:miracle",
            activation: "lucky" as const,
            source: { kind: "gift" as const, actorId },
            sourceDisclosed: false,
            startsOnDay: day,
            maxUses: 1,
          };
          if (skill === "check")
            grantNightAbility(
              ctx.world,
              targetId,
              {
                ...base,
                kind: "seer_check",
                state: { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] },
              },
              ctx.events,
            );
          if (skill === "guard")
            grantNightAbility(
              ctx.world,
              targetId,
              { ...base, kind: "guard", state: { lastTarget: null } },
              ctx.events,
            );
          if (skill === "poison")
            grantNightAbility(
              ctx.world,
              targetId,
              {
                ...base,
                kind: "potion",
                state: {
                  heal: 0,
                  poison: 1,
                  selfHealRule: WitchSelfHealRule.Disabled,
                  canSelfHeal: false,
                  healUsedThisNight: false,
                  poisonUsedThisNight: false,
                },
              },
              ctx.events,
            );
        }
        // Good 授予正常返回后属于已接受前缀；不以晚退休截断商人库存、记录和事实，原抛错仍传播。
        recordMerchantTrade(state, day, targetId, skill as MiracleSkill);
        recordCommit(ctx.world, day);
        if (failure)
          (ctx.state.merchantBacklashes ??= []).push({ target: life, isCurrent: ownerCurrent });
        ctx.events.push({
          timestamp: Date.now(),
          type: "merchant_trade_committed",
          payload: { actorId, day, targetId, skill },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "merchant_trade_resolved",
          payload: { actorId, day, targetId, skill, outcome: failure ? "backlash" : "granted" },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("merchant_valid_action_missing");
    }
  },
};

/**
 * 负责黑市商人在后置受赠行动之前选择交易。输入为原库存与已验证的技能／收货，输出为独立 gift／gun、反噬和事实。
 * 阵营保原捕获／复验点的实际 Camp 值，新请求和未付关窗／首付款之前拒绝退休源，不改变纯目标与知识名单。
 * ownerCurrent（含 paid 首死分支）保已付反噬的原身份／生命政策；Good 资源授予正常返回或 Wolf 首库存写后，
 * 其余库存、选择、记录和事实仍按原前缀完成，原异常传播且不退款，不给替换商人接续已付效果。
 */
import { closeBlackMarketTrade, recordBlackMarketTrade } from "./state";

import { COMPONENT } from "../../../../core/domain/components/names";
import { isRoleExecutionRetired } from "../../../../core/domain/role-execution-authority";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, Phase, WitchSelfHealRule } from "../../../../core/domain/model";
import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { grantNightAbility } from "../night-ability-grants";
import { grantDeathGun } from "../death_abilities";
import { recipientAbilityStage } from "../recipient_ability_stage";
import { canBlackMarketTrade, getBlackMarketState } from "./state";
const committed = new WeakMap<World, Set<number>>();
export function hasBlackMarketNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
function recordCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}
export const BLACK_MARKET_RECIPIENT_STAGE = recipientAbilityStage("black_market", 140);
export const BLACK_MARKET_TRADE_STAGE: NightStageHandler = {
  id: "black_market_merchant",
  priority: 130,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const actorId of ctx.getAliveByRole(Role.BlackMarketMerchant)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getBlackMarketState(role),
        life = captureNightLife(ctx.world, actorId);
      if (!state || !life || ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good) continue;
      const privateState = role.privateState;
      const ownerCurrent = (paid = false) =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.BlackMarketMerchant &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Good &&
        role.privateState === privateState &&
        getBlackMarketState(role) === state &&
        (livingNightLife(ctx.world, life) ||
          (paid &&
            ctx.world.getComponent(actorId, COMPONENT.Alive) === life.life &&
            !life.life.alive &&
            aliveLifeVersion(life.life) === life.version + 1));
      // 先完成原体／库存的原有序复验，再否决新交易；纯 ownerCurrent 仍供已付反噬使用。
      const current = () => ownerCurrent() && canBlackMarketTrade(state, day) && !isRoleExecutionRetired(role);
      if (!current()) continue;
      const skip = () => {
        // null 或原无目标收尾都只是未付关窗；最后一次候选查询能退休源，故在关闭首写前单独拒绝。
        if (isRoleExecutionRetired(role)) return;
        closeBlackMarketTrade(state, day);
        recordCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_skipped",
          payload: { actorId, day },
        });
      };
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        // 候选捕获的原 getter 已全部执行；退休源不再打开新的请求，目标名单本身不按墓碑过滤。
        if (isRoleExecutionRetired(role)) break;
        const action = targets.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(actorId, ["black_market_trade"], {
                stage: "black_market_merchant",
                requiresAction: false,
                action_failure_policy: "error",
                allow_fallback: false,
                ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
              }),
            )
          : null;
        if (!current()) break;
        if (action === null) {
          skip();
          completed = true;
          break;
        }
        if (action.name !== "black_market_trade") continue;
        const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !validated.ok || validated.sanitizedCall?.name !== "black_market_trade")
          continue;
        const { target_id: targetId, skill } = validated.sanitizedCall.args,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          ctx.world.getComponent(targetId, COMPONENT.Camp)?.camp !== target.camp ||
          target.role.privateState !== target.privateState
        )
          continue;
        if (target.camp !== Camp.Good && target.camp !== Camp.Wolf)
          throw new Error("black_market_target_camp_unsupported");
        const failed = target.camp === Camp.Wolf;
        // 原目标 getter／unsupported-Camp 错误仍先发生；只在 Wolf 首付或 Good 资源授予之前拒绝退休源。
        if (isRoleExecutionRetired(role)) break;
        if (!failed) {
          if (skill === "gun") grantDeathGun(ctx.world, actorId, targetId, day, ctx.events);
          else {
            const base = {
              id: "gift:black-market",
              activation: "black_market" as const,
              source: { kind: "gift" as const, actorId },
              sourceDisclosed: false,
              startsOnDay: day + 1,
              maxUses: 1,
            };
            if (skill === "check")
              grantNightAbility(
                ctx.world,
                targetId,
                {
                  ...base,
                  kind: "seer_check",
                  state: { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] },
                },
                ctx.events,
              );
            else
              grantNightAbility(
                ctx.world,
                targetId,
                {
                  ...base,
                  kind: "potion",
                  state: {
                    heal: 0,
                    poison: 1,
                    selfHealRule: WitchSelfHealRule.Disabled,
                    canSelfHeal: false,
                    healUsedThisNight: false,
                    poisonUsedThisNight: false,
                  },
                },
                ctx.events,
              );
          }
        }
        // Good gift／gun 正常返回后不再加墓碑；晚退休不能取消商人库存与已付反噬／通知完成前缀。
        recordBlackMarketTrade(state, day, targetId, skill);
        recordCommit(ctx.world, day);
        const choice = state.choice!;
        if (failed)
          (ctx.state.blackMarketBacklashes ??= []).push({
            target: life,
            isCurrent: () =>
              ownerCurrent(true) &&
              state.choice === choice &&
              choice.day === day &&
              choice.targetId === targetId &&
              choice.skill === skill,
          });
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_committed",
          payload: { actorId, day, targetId, skill },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_resolved",
          payload: { actorId, day, targetId, skill, outcome: failed ? "backlash" : "granted" },
        });
        completed = true;
        break;
      }
      if (!completed && current()) {
        if (ctx.world.getAliveEntityIds().some((id) => id !== actorId))
          throw new Error("black_market_valid_action_missing");
        skip();
      }
    }
  },
};
